using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — demonstrates EF Core 9 breaking change fixes
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "AppDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // EF Core 9 breaking change: default discriminator property renamed
            // from "Discriminator" to "$type". Existing documents use the old name,
            // so we must explicitly preserve it.
            b.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id property no longer includes the
            // discriminator value (was "Session|123", now just "123").
            // Existing documents have the old compound format — preserve it.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string UserId { get; set; } = null!;
    public DateTime ExpiresAt { get; set; }
}

// EF Core 9 breaking change: Cosmos DB provider no longer supports synchronous I/O.
// ToList(), SaveChanges(), etc. now throw. Must use async equivalents.
class SessionService
{
    private readonly CosmosDbContext _db;
    public SessionService(CosmosDbContext db) => _db = db;

    // BEFORE (breaks in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.UserId == userId).ToList();
    //   _db.SaveChanges();

    // AFTER — use async:
    public async Task<List<Session>> GetSessionsAsync(string userId)
    {
        return await _db.Sessions
            .Where(s => s.UserId == userId)
            .ToListAsync();
    }

    public async Task CreateSessionAsync(Session session)
    {
        _db.Sessions.Add(session);
        await _db.SaveChangesAsync();
    }
}

